ALTER TABLE assets ADD CONSTRAINT assets_new_price_ck CHECK (((new_price IS NULL) OR (new_price >= (0)::numeric)));
ALTER TABLE assets ADD CONSTRAINT assets_status_ck CHECK (((status)::text = ANY (ARRAY[('available'::character varying)::text, ('in_use'::character varying)::text, ('defective'::character varying)::text, ('in_repair'::character varying)::text, ('retired'::character varying)::text])));
ALTER TABLE assets ADD CONSTRAINT ck_geraet_garantie CHECK (((warranty_until IS NULL) OR (purchase_date IS NULL) OR (warranty_until >= purchase_date)));
