ALTER TABLE stock_movements ADD CONSTRAINT ck_lagerbewegung_menge CHECK ((quantity > (0)::numeric));
ALTER TABLE stock_movements ADD CONSTRAINT stock_movements_from_condition_ck CHECK (((from_condition IS NULL) OR ((from_condition)::text = ANY (ARRAY[('new'::character varying)::text, ('like_new'::character varying)::text, ('used'::character varying)::text, ('worn'::character varying)::text, ('defective'::character varying)::text]))));
ALTER TABLE stock_movements ADD CONSTRAINT stock_movements_locations_ck CHECK (
CASE movement_type
    WHEN 'receipt'::text THEN ((from_storage_location_id IS NULL) AND (from_condition IS NULL) AND (to_storage_location_id IS NOT NULL) AND (to_condition IS NOT NULL))
    WHEN 'return'::text THEN ((from_storage_location_id IS NULL) AND (from_condition IS NULL) AND (to_storage_location_id IS NOT NULL) AND (to_condition IS NOT NULL))
    WHEN 'removal'::text THEN ((from_storage_location_id IS NULL) AND (from_condition IS NULL) AND (to_storage_location_id IS NOT NULL) AND (to_condition IS NOT NULL))
    WHEN 'issue'::text THEN ((from_storage_location_id IS NOT NULL) AND (from_condition IS NOT NULL) AND (to_storage_location_id IS NULL) AND (to_condition IS NULL))
    WHEN 'installation'::text THEN ((from_storage_location_id IS NOT NULL) AND (from_condition IS NOT NULL) AND (to_storage_location_id IS NULL) AND (to_condition IS NULL))
    WHEN 'disposal'::text THEN ((from_storage_location_id IS NOT NULL) AND (from_condition IS NOT NULL) AND (to_storage_location_id IS NULL) AND (to_condition IS NULL))
    WHEN 'transfer'::text THEN ((from_storage_location_id IS NOT NULL) AND (to_storage_location_id IS NOT NULL) AND (from_storage_location_id <> to_storage_location_id) AND (from_condition IS NOT NULL) AND (to_condition IS NOT NULL) AND ((from_condition)::text = (to_condition)::text))
    WHEN 'condition_change'::text THEN ((from_storage_location_id IS NOT NULL) AND (to_storage_location_id IS NOT NULL) AND (from_storage_location_id = to_storage_location_id) AND (from_condition IS NOT NULL) AND (to_condition IS NOT NULL) AND ((from_condition)::text <> (to_condition)::text))
    WHEN 'adjustment'::text THEN (((from_storage_location_id IS NOT NULL) AND (from_condition IS NOT NULL) AND (to_storage_location_id IS NULL) AND (to_condition IS NULL)) OR ((from_storage_location_id IS NULL) AND (from_condition IS NULL) AND (to_storage_location_id IS NOT NULL) AND (to_condition IS NOT NULL)))
    ELSE false
END);
