CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'extensions', 'public', 'pg_temp'
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.cascade_department_site_to_locations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
    if old.site_id is distinct from new.site_id then
        update public.storage_locations
        set site_id = new.site_id
        where department_id = new.id;
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_stock_movement_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- SQL-Editor / administrative Zugriffe dürfen weiterhin eingreifen.
    IF current_user IN (
        'postgres',
        'supabase_admin',
        'service_role'
    ) THEN
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        END IF;

        RETURN NEW;
    END IF;

    RAISE EXCEPTION
        'Lagerbewegungen dürfen nachträglich nicht geändert oder gelöscht werden. Verwende eine Korrekturbuchung.';
END;
$function$;

CREATE OR REPLACE FUNCTION public.prepare_stock_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'extensions', 'public', 'pg_temp'
AS $function$
DECLARE
    current_quantity numeric(12,3);
    current_tracking_mode text;

    stock_lock bigint;
    created_movement_id bigint;
BEGIN

    -- --------------------------------------------------------
    -- Produktmodell prüfen
    -- --------------------------------------------------------
    SELECT pm.tracking_mode
      INTO current_tracking_mode
    FROM public.product_models pm
    WHERE pm.id = NEW.product_model_id;


    IF current_tracking_mode IS NULL THEN
        RAISE EXCEPTION
            'Produktmodell % wurde nicht gefunden.',
            NEW.product_model_id;
    END IF;


    IF current_tracking_mode NOT IN ('quantity', 'hybrid') THEN
        RAISE EXCEPTION
            'Produktmodell % hat tracking_mode "%". '
            'Inventurzählungen sind nur für quantity oder hybrid erlaubt.',
            NEW.product_model_id,
            current_tracking_mode;
    END IF;


    IF NEW.condition IS NULL THEN
        RAISE EXCEPTION
            'Für die Inventurzählung muss ein Zustand angegeben werden.';
    END IF;


    IF NEW.counted_by_employee_id IS NULL THEN
        RAISE EXCEPTION
            'Für die Inventurzählung muss ein Mitarbeiter angegeben werden.';
    END IF;


    -- --------------------------------------------------------
    -- Genau diesen Bestand sperren:
    -- Produkt + Lagerort + Zustand
    -- --------------------------------------------------------
    stock_lock := hashtextextended(
        NEW.product_model_id::text
        || ':'
        || NEW.storage_location_id::text
        || ':'
        || NEW.condition,
        0
    );

    PERFORM pg_advisory_xact_lock(stock_lock);


    -- --------------------------------------------------------
    -- Sollbestand IMMER automatisch aus stock_levels übernehmen.
    -- Der Client darf expected_quantity nicht manipulieren.
    -- --------------------------------------------------------
    SELECT COALESCE(sl.quantity, 0)
      INTO current_quantity
    FROM public.stock_levels sl
    WHERE sl.product_model_id = NEW.product_model_id
      AND sl.storage_location_id = NEW.storage_location_id
      AND sl.condition = NEW.condition;


    NEW.expected_quantity :=
        COALESCE(current_quantity, 0);


    NEW.difference_quantity :=
        NEW.counted_quantity - NEW.expected_quantity;


    -- Ein eventuell vom Client übergebener Wert wird ignoriert.
    NEW.adjustment_movement_id := NULL;


    -- ========================================================
    -- E. Automatische Korrekturbuchung
    -- ========================================================

    -- --------------------------------------------------------
    -- Es wurden MEHR Stück gezählt als erwartet:
    -- Zugang zum Lagerbestand
    -- --------------------------------------------------------
    IF NEW.difference_quantity > 0 THEN

        INSERT INTO public.stock_movements (
            product_model_id,
            from_storage_location_id,
            to_storage_location_id,
            quantity,
            movement_type,
            moved_at,
            performed_by_employee_id,
            reference,
            note,
            related_asset_id,
            recorded_at,
            from_condition,
            to_condition
        )
        VALUES (
            NEW.product_model_id,
            NULL,
            NEW.storage_location_id,
            NEW.difference_quantity,
            'adjustment',
            NEW.counted_at,
            NEW.counted_by_employee_id,
            'stock_count:' || NEW.id::text,
            'Automatische Inventurkorrektur: Mehrbestand.',
            NULL,
            now(),
            NULL,
            NEW.condition
        )
        RETURNING id
        INTO created_movement_id;


        NEW.adjustment_movement_id :=
            created_movement_id;


    -- --------------------------------------------------------
    -- Es wurden WENIGER Stück gezählt als erwartet:
    -- Abgang vom Lagerbestand
    -- --------------------------------------------------------
    ELSIF NEW.difference_quantity < 0 THEN

        INSERT INTO public.stock_movements (
            product_model_id,
            from_storage_location_id,
            to_storage_location_id,
            quantity,
            movement_type,
            moved_at,
            performed_by_employee_id,
            reference,
            note,
            related_asset_id,
            recorded_at,
            from_condition,
            to_condition
        )
        VALUES (
            NEW.product_model_id,
            NEW.storage_location_id,
            NULL,
            ABS(NEW.difference_quantity),
            'adjustment',
            NEW.counted_at,
            NEW.counted_by_employee_id,
            'stock_count:' || NEW.id::text,
            'Automatische Inventurkorrektur: Minderbestand.',
            NULL,
            now(),
            NEW.condition,
            NULL
        )
        RETURNING id
        INTO created_movement_id;


        NEW.adjustment_movement_id :=
            created_movement_id;

    END IF;


    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    select coalesce(private.current_app_role() = 'admin', false);
$function$;

CREATE OR REPLACE FUNCTION private.validate_software_installation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    license_product_id bigint;
BEGIN
    IF NEW.software_license_id IS NOT NULL THEN

        SELECT software_product_id
        INTO license_product_id
        FROM public.software_licenses
        WHERE id = NEW.software_license_id;

        IF license_product_id IS DISTINCT FROM NEW.software_product_id THEN
            RAISE EXCEPTION
                'Die ausgewählte Software-Lizenz gehört nicht zum Software-Produkt.';
        END IF;

    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.current_app_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    select e.app_role
    from public.employees e
    where e.auth_user_id = (select auth.uid())
      and e.is_active = true
    limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.bump_inventory_change_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    update public.inventory_change_state
    set revision = revision + 1,
        changed_at = now()
    where id = 1;
    return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_negative_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'extensions', 'public', 'pg_temp'
AS $function$
DECLARE
    current_quantity numeric;

    source_lock bigint;
    destination_lock bigint;
BEGIN

    -- --------------------------------------------------------
    -- Lock für Quellbestand
    -- --------------------------------------------------------
    IF NEW.from_storage_location_id IS NOT NULL THEN

        IF NEW.from_condition IS NULL THEN
            RAISE EXCEPTION
                'Bei einem Lagerabgang muss from_condition angegeben werden.';
        END IF;

        source_lock := hashtextextended(
            NEW.product_model_id::text
            || ':'
            || NEW.from_storage_location_id::text
            || ':'
            || NEW.from_condition,
            0
        );

    END IF;


    -- --------------------------------------------------------
    -- Lock für Zielbestand
    -- --------------------------------------------------------
    IF NEW.to_storage_location_id IS NOT NULL THEN

        IF NEW.to_condition IS NULL THEN
            RAISE EXCEPTION
                'Bei einem Lagerzugang muss to_condition angegeben werden.';
        END IF;

        destination_lock := hashtextextended(
            NEW.product_model_id::text
            || ':'
            || NEW.to_storage_location_id::text
            || ':'
            || NEW.to_condition,
            0
        );

    END IF;


    -- --------------------------------------------------------
    -- Locks deterministisch setzen, um Deadlocks zu vermeiden
    -- --------------------------------------------------------
    IF source_lock IS NOT NULL
       AND destination_lock IS NOT NULL THEN

        IF source_lock = destination_lock THEN

            PERFORM pg_advisory_xact_lock(source_lock);

        ELSE

            PERFORM pg_advisory_xact_lock(
                LEAST(source_lock, destination_lock)
            );

            PERFORM pg_advisory_xact_lock(
                GREATEST(source_lock, destination_lock)
            );

        END IF;

    ELSIF source_lock IS NOT NULL THEN

        PERFORM pg_advisory_xact_lock(source_lock);

    ELSIF destination_lock IS NOT NULL THEN

        PERFORM pg_advisory_xact_lock(destination_lock);

    END IF;


    -- --------------------------------------------------------
    -- Bei reinem Zugang muss nichts auf Negativbestand
    -- geprüft werden.
    -- --------------------------------------------------------
    IF NEW.from_storage_location_id IS NULL THEN
        RETURN NEW;
    END IF;


    SELECT COALESCE(sl.quantity, 0)
      INTO current_quantity
    FROM public.stock_levels sl
    WHERE sl.product_model_id = NEW.product_model_id
      AND sl.storage_location_id = NEW.from_storage_location_id
      AND sl.condition = NEW.from_condition;


    current_quantity := COALESCE(current_quantity, 0);


    IF current_quantity < NEW.quantity THEN

        RAISE EXCEPTION
            'Nicht genügend Lagerbestand. '
            'Produktmodell: %, Lagerort: %, Zustand: %, '
            'verfügbar: %, benötigt: %.',
            NEW.product_model_id,
            NEW.from_storage_location_id,
            NEW.from_condition,
            current_quantity,
            NEW.quantity;

    END IF;


    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_asset_component_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'extensions', 'public', 'pg_temp'
AS $function$
BEGIN
    IF NEW.removed_at IS NOT NULL THEN
        RETURN NEW;
    END IF;

    IF NEW.parent_asset_id = NEW.child_asset_id THEN
        RAISE EXCEPTION 'Ein Asset kann nicht seine eigene Komponente sein.';
    END IF;

    IF EXISTS (
        WITH RECURSIVE descendants AS (
            SELECT aca.child_asset_id
            FROM public.asset_component_assignments aca
            WHERE aca.parent_asset_id = NEW.child_asset_id
              AND aca.removed_at IS NULL
              AND aca.id <> COALESCE(NEW.id, -1)

            UNION

            SELECT aca.child_asset_id
            FROM public.asset_component_assignments aca
            JOIN descendants d
              ON aca.parent_asset_id = d.child_asset_id
            WHERE aca.removed_at IS NULL
              AND aca.id <> COALESCE(NEW.id, -1)
        )
        SELECT 1
        FROM descendants
        WHERE child_asset_id = NEW.parent_asset_id
    ) THEN
        RAISE EXCEPTION 'Die Komponentenzuordnung würde einen Zyklus erzeugen.';
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.write_inventory_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_employee_id bigint;
    v_entity_id bigint;
BEGIN

    SELECT e.id
    INTO v_employee_id
    FROM public.employees e
    WHERE e.auth_user_id = auth.uid()
    LIMIT 1;


    IF TG_OP = 'DELETE' THEN
        v_entity_id := OLD.id;
    ELSE
        v_entity_id := NEW.id;
    END IF;


    INSERT INTO public.audit_log (
        entity_type,
        entity_id,
        action,
        changed_by_employee_id,
        changed_by_auth_user_id,
        old_data,
        new_data
    )
    VALUES (
        TG_TABLE_NAME,
        v_entity_id,
        lower(TG_OP),
        v_employee_id,
        auth.uid(),

        CASE
            WHEN TG_OP = 'INSERT' THEN NULL
            ELSE to_jsonb(OLD)
        END,

        CASE
            WHEN TG_OP = 'DELETE' THEN NULL
            ELSE to_jsonb(NEW)
        END
    );


    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.can_edit_inventory()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    select coalesce(private.current_app_role() in ('admin', 'user'), false);
$function$;

CREATE OR REPLACE FUNCTION private.sync_department_site_mapping()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
    if tg_op = 'DELETE' then
        delete from public.site_departments
        where department_id = old.id;
        return old;
    end if;

    delete from public.site_departments
    where department_id = new.id;

    insert into public.site_departments (site_id, department_id)
    values (new.site_id, new.id)
    on conflict do nothing;

    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.validate_stock_tracking_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'extensions', 'public', 'pg_temp'
AS $function$
DECLARE
    mode text;
BEGIN
    SELECT pm.tracking_mode
      INTO mode
    FROM public.product_models pm
    WHERE pm.id = NEW.product_model_id;

    IF mode NOT IN ('quantity', 'hybrid') THEN
        RAISE EXCEPTION
            'Produktmodell % hat tracking_mode %, darf daher nicht über Mengenbewegungen geführt werden.',
            NEW.product_model_id,
            mode;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.sync_storage_location_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
    department_site_id bigint;
begin
    if new.department_id is null then
        raise exception 'Lagerort benötigt eine Abteilung.';
    end if;

    select d.site_id
    into department_site_id
    from public.departments d
    where d.id = new.department_id;

    if department_site_id is null then
        raise exception 'Die gewählte Abteilung besitzt keinen Standort.';
    end if;

    new.site_id := department_site_id;
    new.is_active := true;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.can_read_inventory()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    select coalesce(private.current_app_role() in ('admin', 'user', 'viewer'), false);
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION private.prevent_last_itassetflow_admin_removal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    if old.app_role = 'admin'
       and old.is_active = true
       and old.auth_user_id is not null
       and (
           tg_op = 'DELETE'
           or new.app_role <> 'admin'
           or new.is_active = false
           or new.auth_user_id is null
       )
       and not exists (
           select 1
             from public.employees e
            where e.id <> old.id
              and e.app_role = 'admin'
              and e.is_active = true
              and e.auth_user_id is not null
       ) then
        raise exception 'Der letzte aktive Administrator kann nicht entfernt oder herabgestuft werden.';
    end if;

    if tg_op = 'DELETE' then
        return old;
    end if;
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.validate_asset_tracking_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'extensions', 'public', 'pg_temp'
AS $function$
DECLARE
    mode text;
BEGIN
    SELECT pm.tracking_mode
      INTO mode
    FROM public.product_models pm
    WHERE pm.id = NEW.product_model_id;

    IF mode NOT IN ('serialized', 'hybrid') THEN
        RAISE EXCEPTION
            'Produktmodell % hat tracking_mode %, darf daher nicht als einzelnes Asset geführt werden.',
            NEW.product_model_id,
            mode;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.provision_itassetflow_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
    v_employee_id bigint;
begin
    if new.email is null or btrim(new.email) = '' then
        return new;
    end if;

    select e.id
      into v_employee_id
      from public.employees e
     where e.auth_user_id = new.id
        or (
            e.auth_user_id is null
            and e.email is not null
            and lower(e.email) = lower(new.email)
        )
     order by case when e.auth_user_id = new.id then 0 else 1 end, e.id
     limit 1;

    if v_employee_id is null then
        insert into public.employees (
            first_name,
            last_name,
            email,
            is_active,
            auth_user_id,
            app_role
        )
        values (
            coalesce(nullif(btrim(new.raw_user_meta_data ->> 'first_name'), ''), 'Benutzer'),
            coalesce(nullif(btrim(new.raw_user_meta_data ->> 'last_name'), ''), split_part(new.email, '@', 1)),
            new.email,
            true,
            new.id,
            'viewer'
        );
    else
        update public.employees
           set auth_user_id = new.id,
               email = new.email,
               is_active = true,
               app_role = case
                   when auth_user_id is null then 'viewer'
                   else app_role
               end
         where id = v_employee_id;
    end if;

    return new;
end;
$function$;

CREATE TRIGGER asset_component_assignments_cycle_trg BEFORE INSERT OR UPDATE OF parent_asset_id, child_asset_id, removed_at ON public.asset_component_assignments FOR EACH ROW EXECUTE FUNCTION prevent_asset_component_cycle();
