CREATE TRIGGER departments_sync_site_mapping_trg AFTER INSERT OR DELETE OR UPDATE OF site_id ON public.departments FOR EACH ROW EXECUTE FUNCTION private.sync_department_site_mapping();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.asset_assignments FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.asset_component_assignments FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.asset_locations FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.assets FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.departments FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.employees FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.manufacturers FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.product_categories FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.product_models FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.stock_counts FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.stock_movements FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER itassetflow_inventory_revision AFTER INSERT OR DELETE OR UPDATE ON public.storage_locations FOR EACH STATEMENT EXECUTE FUNCTION bump_inventory_change_revision();
CREATE TRIGGER prevent_last_itassetflow_admin_removal BEFORE DELETE OR UPDATE ON public.employees FOR EACH ROW EXECUTE FUNCTION private.prevent_last_itassetflow_admin_removal();
CREATE TRIGGER product_models_audit_trg AFTER INSERT OR DELETE OR UPDATE ON public.product_models FOR EACH ROW EXECUTE FUNCTION write_inventory_audit();
CREATE TRIGGER product_models_set_updated_at BEFORE UPDATE ON public.product_models FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER software_installations_validate_license BEFORE INSERT OR UPDATE OF software_product_id, software_license_id ON public.software_installations FOR EACH ROW EXECUTE FUNCTION private.validate_software_installation();
CREATE TRIGGER stock_counts_prepare_trg BEFORE INSERT ON public.stock_counts FOR EACH ROW EXECUTE FUNCTION prepare_stock_count();
CREATE TRIGGER stock_movements_immutable_trg BEFORE DELETE OR UPDATE ON public.stock_movements FOR EACH ROW EXECUTE FUNCTION prevent_stock_movement_mutation();
CREATE TRIGGER stock_movements_negative_stock_trg BEFORE INSERT ON public.stock_movements FOR EACH ROW EXECUTE FUNCTION prevent_negative_stock();
CREATE TRIGGER stock_movements_tracking_mode_trg BEFORE INSERT OR UPDATE OF product_model_id ON public.stock_movements FOR EACH ROW EXECUTE FUNCTION validate_stock_tracking_mode();
CREATE TRIGGER storage_locations_sync_hierarchy_trg BEFORE INSERT OR UPDATE OF department_id, site_id, is_active ON public.storage_locations FOR EACH ROW EXECUTE FUNCTION private.sync_storage_location_hierarchy();
CREATE VIEW public.stock_levels WITH (security_invoker=true) AS  WITH movements AS (
         SELECT stock_movements.product_model_id,
            stock_movements.to_storage_location_id AS storage_location_id,
            stock_movements.quantity AS delta,
            stock_movements.to_condition AS condition
           FROM stock_movements
          WHERE stock_movements.to_storage_location_id IS NOT NULL AND stock_movements.to_condition IS NOT NULL
        UNION ALL
         SELECT stock_movements.product_model_id,
            stock_movements.from_storage_location_id AS storage_location_id,
            - stock_movements.quantity AS delta,
            stock_movements.from_condition AS condition
           FROM stock_movements
          WHERE stock_movements.from_storage_location_id IS NOT NULL AND stock_movements.from_condition IS NOT NULL
        )
 SELECT product_model_id,
    storage_location_id,
    sum(delta) AS quantity,
    condition
   FROM movements
  GROUP BY product_model_id, storage_location_id, condition;
CREATE VIEW public.stock_levels_total WITH (security_invoker=true) AS  SELECT product_model_id,
    storage_location_id,
    sum(quantity) AS quantity
   FROM stock_levels
  GROUP BY product_model_id, storage_location_id;
GRANT USAGE ON SCHEMA public, private, auth TO authenticated, anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated;
